def transform(grid):
    result = []
    for row in grid:
        left = row[:6]   # cols 0-5 (6 positions)
        # Right side starts at column 7
        right = row[7:]  # cols 7-12 (6 positions)
        out = [0] * 6  # Initialize all to 0, then set non-triggers to 3
        for k in range(6):
            if left[k] != 2 and right[k] != 5:
                out[k] = 3
        result.append(out)
    return result

